INSERT INTO projects (id, title, description, long_description, image, github_url, position) VALUES ('68d0376c2f34c616e517b141', 'SatvaFarm: Plant Disease Detection and Government Scheme Portal', 'A web application to help farmers detect plant diseases by uploading images and to provide information about relevant government schemes. It also includes a knowledge base with articles about agriculture.', 'AgriCare is a comprehensive platform for farmers. It leverages machine learning for plant disease detection. Users can upload images of their plants and get instant feedback on their health. The application also serves as a portal for discovering and applying for government schemes related to agriculture. A rich knowledge base with articles and guides is available to keep farmers informed about the latest agricultural practices. The platform requires user authentication and has a verification system using ID proofs. The frontend is a modern single-page application built with React.', 'https://defiant-lavender-ypeckrufll.edgeone.app/SatvaFarmBanner.jpg', 'https://github.com/ShahHet2812/SatvaFarm', 1);
