INSERT INTO testimonials (id, name, role, avatar, text, position) VALUES ('68cc3c3590dcd192e5e7b9c3', 'Aayush Pandya', '2-time Hackathon Partner and Classmate', 'https://testimonials.edgeone.app/aayush.jpg', 'Your invaluable co-operation in the highly significant project presented by our university was very much appreciated. Your intellectual capabilities were of great help in completion of the project.Your quick responses during the presentation certainly solidified a respectable score which helped us with end term results', 0);
INSERT INTO testimonials (id, name, role, avatar, text, position) VALUES ('68cc3c3590dcd192e5e7b9c4', 'Moksh Kothari', 'Classmate', 'https://testimonials.edgeone.app/moksh.jpg', 'The kind of college-mate on whom one can trust. Best encouragement provider and always ready to support the group.', 1);
INSERT INTO testimonials (id, name, role, avatar, text, position) VALUES ('68cc3c3590dcd192e5e7b9c5', 'Yashesh Mehta', '1-time Hackathon Partner and Classmate', 'https://testimonials.edgeone.app/Yashesh.png', 'Working with Het on our college project was a great experience for me. He was not only a good team-mate, but also a good supporter. With his quick intellect and problem solving skills, he always found out a way in any kind of problems. He is a quick learner and is always motivates others to do the best out of them. He also has good analytical thinking which helped us a lot in the project. I''m grateful that I''ve got a chance to work with him.', 2);
INSERT INTO hackathons (id, title, event_date, duration, image, description, achievement, team_size, git_url, project_url, video_url, sort_date) VALUES ('68cc361d766beb82d9905f55', 'Hackovate 2025', 'September 13-14,2025', '36 hours', 'https://hackathon.edgeone.app/LJ.jpg', 'An AI/ML-powered Cattle Analytics Platform built in 36 hours. It predicts milk yield, detects cattle diseases, and provides multilingual veterinary guidance. The solution integrates XGBoost regression and classification models, explainability with SHAP, PDF report generation, and an AI chatbot specialized in cattle health.', 'Built and deployed a complete AI-driven cattle monitoring solution in 36 hours.', 3, 'https://github.com/ShahHet2812/Hackovate', 'https://codeblooded.streamlit.app', NULL, '2025-09-13');
