INSERT INTO hackathons (id, title, event_date, duration, image, description, achievement, team_size, git_url, project_url, video_url, sort_date) VALUES ('68cc3148766beb82d9905f52', 'Odoo Hackathon 2025', 'August 11–12, 2025', '24 hours', 'https://hackathon.edgeone.app/odoo.jpg', 'Our team made it to the offline round of Odoo Hackathon 2025 after clearing the online round with a rank of 335 out of 2000+ registrations. We spent 24 intense hours at Gandhinagar collaborating, coding, and delivering a complete project as per the problem statement. It was a thrilling experience filled with teamwork, late-night hustle, and lots of learning.', 'Advanced to offline round and delivered a full solution.', 3, 'https://github.com/ShahHet2812/Odoo-2k25', 'https://quick-court-two.vercel.app/', 'https://drive.google.com/file/d/1xC402o-EfBtExk84rPTkNfECj81tOtv2/view?usp=drive_link', '2025-08-11');
