INSERT INTO hackathons (id, title, event_date, duration, image, description, achievement, team_size, git_url, project_url, video_url, sort_date) VALUES ('68cc2f75766beb82d9905f50', 'HackNUthon 2025', 'March 29–31, 2025', '3 days', 'https://hackathon.edgeone.app/nirma.jpg', 'We built a Smart Kitchen System for Petpooja that identifies food objects using Computer Vision, links to an inventory dashboard for real-time stock tracking, implements a waste management system powered by Machine Learning, and suggests recipes using the MealDB API by prioritizing ingredients nearing expiry. The project aimed to reduce food waste and optimize kitchen management with AI-driven solutions.', 'Built an AI-powered Smart Kitchen prototype in 3 days.', 4, 'https://github.com/swapnil05patel/TechGPT', NULL, 'https://youtu.be/jBrCSYz8kAE', '2025-03-29');
